-- QA ONLY. Exact Lua5.3 BigInt 96-prefix differential; PROJECT_ID=PC-BRANCH-LUA-HAITIAN.
-- Frozen Python fixture is external and is never generated by this program.
local ACTUAL={123,92,119,123,121,120,116,116,95,114,120,121,115,116,104,113,121,120,119,117,123,86,123,117,115,108,81,116,120,112,120,116,115,120,123,114,123,89,122,116,115,79,117,123,92,122,82}
local BASE=10000000
local ZERO,ONE={0},{1}
local function trim(a) while #a>1 and a[#a]==0 do a[#a]=nil end return a end
local function copy(a) local b={} for i=1,#a do b[i]=a[i] end return b end
local function cmp(a,b)
if #a~=#b then return #a<#b and -1 or 1 end
for i=#a,1,-1 do if a[i]~=b[i] then return a[i]<b[i] and -1 or 1 end end
return 0
end
local function add(a,b)
local out,carry={},0
for i=1,math.max(#a,#b) do
local x=(a[i] or 0)+(b[i] or 0)+carry
if x>=BASE then out[i]=x-BASE;carry=1 else out[i]=x;carry=0 end
end
if carry~=0 then out[#out+1]=carry end
return out
end
local function sub(a,b)
assert(cmp(a,b)>=0,'negative BigInt subtraction')
local out,borrow={},0
for i=1,#a do
local x=a[i]-(b[i] or 0)-borrow
if x<0 then x=x+BASE;borrow=1 else borrow=0 end
out[i]=x
end
assert(borrow==0)
return trim(out)
end
local function mul(a,b)
if cmp(a,ZERO)==0 or cmp(b,ZERO)==0 then return {0} end
local out={}
for i=1,#a+#b+1 do out[i]=0 end
for i=1,#a do
local carry=0
for j=1,#b do
local k=i+j-1
local x=out[k]+a[i]*b[j]+carry
local z=math.floor(x/BASE)
out[k]=x-z*BASE;carry=z
end
local k=i+#b
while carry>0 do
local x=out[k]+carry
local z=math.floor(x/BASE)
out[k]=x-z*BASE;carry=z;k=k+1
end
end
return trim(out)
end
local function mulsmall(a,z)
assert(z==math.floor(z) and z>=0 and z<=6000,'small multiplier out of bounds')
if z==0 then return {0} end
local out,carry={},0
for i=1,#a do
local x=a[i]*z+carry
local k=math.floor(x/BASE)
out[i]=x-k*BASE;carry=k
end
while carry>0 do out[#out+1]=carry%BASE;carry=math.floor(carry/BASE) end
return out
end
local function divsmall(a,z,require_exact)
assert(z==math.floor(z) and z>=1 and z<=6000,'small divisor out of bounds')
local out,rem={},0
for i=#a,1,-1 do
local x=rem*BASE+a[i]
local k=math.floor(x/z)
out[i]=k;rem=x-k*z
end
if require_exact then assert(rem==0,'non-exact BigInt division') end
return trim(out),rem
end
local function decimal(a)
local parts={tostring(a[#a])}
for i=#a-1,1,-1 do parts[#parts+1]=string.format('%07d',a[i]) end
return table.concat(parts)
end
local function source_vector(n)
assert(type(n)=='table' and #n>=1 and #n<=47,'unsupported label count')
local p={[0]=0}
for i,v in ipairs(n) do
assert(type(v)=='number' and v==math.floor(v) and v>=2,'invalid month length')
p[i]=p[i-1]+v
end
assert(p[#n]<=6000,'QA length cap exceeded')
return p
end
local function make_rows(months,p,maxprefix)
local width=maxprefix+#months+1
local saved={}
local nextrow={}
for q=0,p[#months] do nextrow[q]=ONE end
local function retain(a,row)
local sparse={}
for q=math.max(0,p[a]-width),p[a] do sparse[q]=row[q] end
saved[a]=sparse
end
retain(#months,nextrow)
for a=#months-1,0,-1 do
local n=months[a+1]
local row={[0]=nextrow[n-1]}
local choose=ONE
for q=1,p[a] do
choose=divsmall(mulsmall(choose,q+n-2),q,true)
row[q]=add(row[q-1],mul(choose,nextrow[q+n-1]))
end
retain(a,row)
nextrow=row
collectgarbage('collect')
end
return saved
end
local choose_cache={}
local function choose_small(n,k)
assert(n>=0 and k>=0 and k<=n)
k=math.min(k,n-k)
if k==0 then return ONE end
local key=n..':'..k
if choose_cache[key] then return choose_cache[key] end
local c=ONE
for i=1,k do c=divsmall(mulsmall(c,n-k+i),i,true) end
choose_cache[key]=c
return c
end
local function suffix(rem,opened,closed,rows,p,step)
local q=0
local ways=ONE
for j=closed+1,opened do
local r=rem[j]
assert(r and r>=1,'active empty month')
q=q+r
ways=mul(ways,choose_small(q-1,r-1))
end
assert(q==p[opened]-step,'suffix active-sum invariant')
local base=rows[opened][q]
assert(base,'sparse DP row missing a='..opened..' q='..q)
return mul(ways,base)
end
local function candidate(rem,months,opened,closed,j)
local r=rem[j]
if not r or r<1 then return nil end
if j==opened+1 then
if j>#months or r~=months[j] then return nil end
return opened+1,closed
end
if j<=closed or j>opened or r==months[j] then return nil end
if r==1 and j~=closed+1 then return nil end
return opened,closed+(r==1 and 1 or 0)
end
local function unrank(months,p,rows,rank,limit)
assert(type(limit)=='number' and limit==math.floor(limit) and limit>=0 and limit<=p[#months], 'invalid prefix limit')
assert(type(rank)=='table' and cmp(rank,ZERO)>0,'rank must be positive BigInt')
assert(cmp(rank,rows[0][0])<=0,'rank above total')
rank=copy(rank)
local rem=copy(months)
local opened,closed,labels=0,0,{}
local evaluations=0
for step=0,limit-1 do
local current=suffix(rem,opened,closed,rows,p,step)
local sum=ZERO
local selected,rrank
for j=closed+1,math.min(opened+1,#months) do
local op,cl=candidate(rem,months,opened,closed,j)
if op then
rem[j]=rem[j]-1
local block=suffix(rem,op,cl,rows,p,step+1)
rem[j]=rem[j]+1
evaluations=evaluations+1
assert(evaluations<=15000,'QA branch-evaluation cap')
sum=add(sum,block)
if not selected then
if cmp(rank,block)>0 then rank=sub(rank,block)
else selected={j,op,cl};rrank=copy(rank) end
end
end
end
assert(cmp(sum,current)==0,'disjoint prefix partition differs from remaining count at '..step)
assert(selected,'lexicographic rank lacks a block')
local j,op,cl=selected[1],selected[2],selected[3]
labels[#labels+1]=tostring(j-1)
rem[j]=rem[j]-1
opened,closed=op,cl
rank=rrank
end
local final=suffix(rem,opened,closed,rows,p,limit)
assert(cmp(rank,ONE)>=0 and cmp(rank,final)<=0,'residual rank out of bounds')
return table.concat(labels,','),decimal(rank),decimal(final),evaluations
end
local function exhaustive_words(months)
local remain=copy(months)
local seq,out={},{}
local len=0
for _,n in ipairs(months) do len=len+n end
local function visit(pos)
if pos>len then
local first,last={},{}
for i,j in ipairs(seq) do if not first[j] then first[j]=i end;last[j]=i end
for j=2,#months do if not(first[j-1]<first[j] and last[j-1]<last[j]) then return end end
local word={}
for i,j in ipairs(seq) do word[i]=tostring(j-1) end
out[#out+1]=table.concat(word,',')
return
end
for j=1,#months do
if remain[j]>0 then
remain[j]=remain[j]-1;seq[pos]=j
visit(pos+1)
remain[j]=remain[j]+1
end
end
end
visit(1)
return out
end
local function small_tests()
local tiny={{2,2},{3,2},{2,2,2},{2,3,2},{3,3},{2,2,2,2}}
local ranks=0
for _,v in ipairs(tiny) do
local p=source_vector(v)
local rows=make_rows(v,p,p[#v])
local words=exhaustive_words(v)
assert(cmp(rows[0][0],{#words})==0,'small domain total mismatch')
for k,w in ipairs(words) do
local got,res,suffixval=unrank(v,p,rows,{k},p[#v])
assert(got==w and res=='1' and suffixval=='1','small exhaustive rank mismatch')
ranks=ranks+1
end
local ok=pcall(unrank,v,p,rows,ZERO,p[#v]);assert(not ok,'rank zero accepted')
ok=pcall(unrank,v,p,rows,add(rows[0][0],ONE),p[#v]);assert(not ok,'rank above N accepted')
ok=pcall(unrank,v,p,rows,ONE,p[#v]+1);assert(not ok,'prefix beyond L accepted')
end
for _,v in ipairs({{}, {1}, {2,1}, {2,2.5}}) do
assert(not pcall(source_vector,v),'invalid vector accepted')
end
print('SMALL_EXHAUSTIVE=PASS domains='..#tiny..' ranks='..ranks..' invalid_vectors=4 rank_rejects=18')
end
local mode=(arg and arg[1]) or 'selftest'
assert(_VERSION=='Lua 5.3' or _VERSION=='Lua 5.4','Lua 5.3-compatible runtime required')
assert(mode=='selftest' or mode=='real','supported modes: selftest or real')
small_tests()
if mode=='real' then
assert(type(arg[2])=='string' and #arg[2]>0,'output TSV path required')
local p=source_vector(ACTUAL)
assert(#ACTUAL==47 and p[#ACTUAL]==5294,'attested real vector mismatch')
local t=os.clock()
local rows=make_rows(ACTUAL,p,96)
local total=rows[0][0]
assert(#decimal(total)==8654,'real total decimal length mismatch')
local midpoint=divsmall(add(total,ONE),2,false)
local out=assert(io.open(arg[2],'wb'))
for _,x in ipairs({{'FIRST',ONE},{'MIDDLE',midpoint},{'LAST',total}}) do
local prefix,residual,card,branches=unrank(ACTUAL,p,rows,x[2],96)
out:write(x[1],'\t',prefix,'\t',residual,'\t',card,'\n')
print('REAL96='..x[1]..' labels=96 residual_digits='..#residual..' suffix_digits='..#card..' branch_evaluations='..branches)
out:flush()
end
out:close()
print('REAL96_LUA53=COMPUTED witnesses=3 cpu_seconds='..string.format('%.2f',os.clock()-t))
print('QA_ONLY=PASS FULL_DATE_NOT_RUN=1 NORMATIVE_WEAVING_NOT_RUN=1')
end
